INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'frFR', 'Récupérer 5 particules d\’investigation omniale pour les utiliser dans le feuillet de l\’Omnium.', 'Étude du feuillet de l\’Omnium', 'Élément de décoration : simulacre de l\’Omnium de Haut-Soleil', 68974),
(62903, 'frFR', 'Dissiper 5 tempêtes sur Val.', 'Drôle de climat : Val', 'Mascotte : Vibriss Lissé disponible à l\’achat', 68974),
(63343, 'frFR', 'Marquez un but avec la balle d\’entraînement tirable de Lune-d\’Argent en portant un tabard de participation.', 'But !', 'Élément de décoration : orbe précieux d\’Azeroth, fierté de la Horde encadrée et fierté de l\’Alliance encadrée', 68974),
(61336, 'frFR', 'Honorer les flammes de Midnight.', 'Gardien ou gardienne des flammes de Midnight', '', 68974),
(61335, 'frFR', 'Honorer les flammes de Midnight.', 'Garde-flammes de Midnight', '', 68974),
(61936, 'frFR', 'Vaincre l\’avant-garde lumaveuglée pendant que votre groupe a Aura maximale dans la flèche du Vide en mode normal ou supérieur.', 'Exploitation d\’aura', '', 68974),
(61911, 'frFR', 'Vaincre Vaelgor et Ezzorak après que tous les personnages-joueurs ont brisé chacune des attaches de la bulle de néant en moins de 3 s dans la flèche du Vide en mode normal ou supérieur.', 'À vos marques, prêts, coupez !', '', 68974),
(61514, 'frFR', 'Vaincre le roi déchu Salhadaar après que tout le monde se soit mis à genoux devant lui avant le début du combat dans la flèche du Vide en mode normal ou supérieur.', 'Trahison manifeste', '', 68974),
(61381, 'frFR', 'Vaincre Belo\’ren, enfant d\’Al\’ar, après avoir imprégné l\’œuf du Puits de soleil de magie de la Lumière et du Vide dans la marche sur Quel\’Danas en mode normal ou supérieur.', 'Ne pas mettre tous ses œufs dans le même nid', '', 68974),
(61346, 'frFR', 'Vaincre la Couronne du cosmos après avoir tué une monstruosité de chair et rapporté toute sa chair à la Vacuité dans la flèche du Vide en mode normal ou supérieur.', 'De fait, nous la reverrons', '', 68974),
(61611, 'frFR', 'Vaincre le Glas de minuit de la marche sur Quel\’Danas en mode mythique et en groupe de guilde.', 'Virée en guilde sur le Glas de minuit : mode mythique', '', 68974),
(61380, 'frFR', 'Accomplir les hauts faits de raid listés ci-dessous.', 'Gloire à l\’écumage des raids de Midnight', 'Monture : Persécuteur ténébreux', 68974),
(62874, 'frFR', 'Accomplir les hauts faits listés ci-dessous.', 'Périple interstellaire', 'Récompense : Exossature néantine forge-néant disponible à l\’achat', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'frFR', 'Feuillet de l\’Omnium : nouvelles informations', 'Les Magistères disposent d\’informations supplémentaires susceptibles de renforcer davantage de runes du feuillet de l\’Omnium.', 'Accepter la quête', 'Accomplissez cette quête pour remporter une particule d\’investigation omniale et renforcer une autre rune à partir du feuillet de l\’Omnium.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'frFR', 'Tanière de Prédaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'frFR', 'MODE DÉTENTE : ACTIVÉ.\nNIVEAU DE DÉTENTE : MAXIMAL.\nTEMPÉRATURE INTERNE : BASSE.', '|cFFFFD200Promotion|r |n', 68974),
(4617, 'frFR', 'DIRECTIVE PRINCIPALE : COMMETTRE DES ACTES HÉROÏQUES.\nHÉROÏSME PRÉFÉRÉ : EXTRÊME.\nDIRECTIVE SECONDAIRE : DEVENIR HÉROÏQUE.\nHÉROS PRÉFÉRÉ : GRAND.', '|cFFFFD200Promotion|r |n', 68974),
(4949, 'frFR', 'Un vestige résiduel de la tentative de Fyrakka de corrompre Amirdrassil.', '|cFFFFD200Vendeur : |rXydan|n|cFFFFD200Région : |rValdrakken|n|cFFFFD200Coût : |r2 200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'frFR', 'À la différence des marcheurs de la tempête du Vide, Silento affectionne le calme et la quiétude du silence. Quitte à réduire au silence les plus loquaces de son espèce.', '|cFFFFD200Hauts faits :|r Confrontation réussie : Val et Confrontation réussie : Naigtal|n|cFFFFD200Vendeur :|r Kifaan|n|cFFFFD200Régions :|r Val ou Naigtal|n|cFFFFD200Coût :|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'frFR', 'Cette petite créature est prête à tout saccager pour honorer ses ancêtres. Elle va commencer par de petites araignées avant de viser plus grand.', '|cFFFFD200Haut fait :|r Massacre à l\’ultradon|n|cFFFFD200Vendeur :|r Kifaan|n|cFFFFD200Régions :|r Val ou Naigtal|n|cFFFFD200Coût :|r 15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'frFR', 'Vibriss adore le poisson congelé. Si vous en avez sur vous, préparez-vous à vous faire un nouvel ami.', '|cFFFFD200Haut fait :|r Drôle de climat : Val|n|cFFFFD200Vendeur :|r Kifaan|n|cFFFFD200Régions :|r Naigtal ou Val|n|cFFFFD200Coût :|r 50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'frFR', 'Le commandant Tala\’saan retire sa cape voilumière et s\’avance.', '', 68974),
(314421, 'frFR', 'AAARH !', '', 68974),
(314420, 'frFR', 'ZUL\’JAN, ATTENTION !', '', 68974),
(314419, 'frFR', 'ni des hash\’ey !', '', 68974),
(314418, 'frFR', 'Avec ce pouvoir, nous n\’aurons besoin ni des Loas...', '', 68974),
(314417, 'frFR', 'Non !', '', 68974),
(314416, 'frFR', 'Lâche ça !', '', 68974),
(314415, 'frFR', 'C\’est de la magie noire !', '', 68974),
(314414, 'frFR', 'Zul\’jan !', '', 68974),
(314413, 'frFR', '(grognement)', '', 68974),
(314412, 'frFR', 'Ce doit être… la clé de…', '', 68974),
(314411, 'frFR', 'Je l\’ai trouvée !', '', 68974),
(314410, 'frFR', 'Ah !', '', 68974),
(314408, 'frFR', '… je t\’assure… qu\’elle comprendra.', '', 68974),
(314407, 'frFR', 'Quand tu manieras la puissance d\’Ula\’tek…', '', 68974),
(314406, 'frFR', 'Prends la clé, Zul\’jan.', '', 68974),
(314405, 'frFR', 'Quand elle verra notre oncle…', '', 68974),
(314404, 'frFR', 'Les Loas l\’ont complètement endoctrinée…', '', 68974),
(314403, 'frFR', 'Ma sœur s\’y opposera.', '', 68974),
(314402, 'frFR', 'Pour finir ce que ton grand-père et moi avions commencé.', '', 68974),
(314401, 'frFR', 'sans compter sur les vaines promesses des Loas.', '', 68974),
(314400, 'frFR', 'Pour sauver l\’avenir de notre peuple,', '', 68974),
(314399, 'frFR', 'et j\’ai besoin de ton aide, Zul\’jan.', '', 68974),
(314398, 'frFR', 'Malacrass,', '', 68974),
(314397, 'frFR', 'Oui…', '', 68974),
(314396, 'frFR', 'Alors vous devez être…', '', 68974),
(314395, 'frFR', 'Vous avez connu mon grand-père ?', '', 68974),
(314394, 'frFR', 'Zul\’jin et moi cherchions à changer les choses…', '', 68974),
(314393, 'frFR', 'Malheureusement, c\’est le destin de notre peuple.', '', 68974),
(314392, 'frFR', '… sans qu\’ils soient présents lors de son dernier soupir.', '', 68974),
(314391, 'frFR', 'Une vie passée à vénérer ses Loas…', '', 68974),
(314390, 'frFR', 'Quelle tragédie.', '', 68974),
(314389, 'frFR', 'Non, non, non, je n\’ai… non.', '', 68974),
(314388, 'frFR', 'Non…', '', 68974),
(314387, 'frFR', 'Il est mort, Zul\’jan.', '', 68974),
(314386, 'frFR', 'KINDURU !', '', 68974),
(314385, 'frFR', 'Kinduru ?!', '', 68974),
(314384, 'frFR', '(toux)', '', 68974),
(310355, 'frFR', 'Et je vais fouiller la flèche d\’Aubétoile pour trouver le composant manquant. Rejoignez-moi dès que possible, $n. Et Rommath, bonne chance.', '', 68974),
(317801, 'frFR', '<Tala\’saan réfléchit à la question, le regard momentanément absent.>\n\nLa capitaine Fareeya ne participera pas à cette opération.\n\nJe la représente auprès des Sancteforge qui participent à la mission de Maella.\n\nAvec la perte du grand exarque et d\’innombrables autres âmes, l\’armée de la Lumière a besoin de son commandement maintenant, plus que jamais.\n\nHeureusement, nous ne sommes pas sans soutien. Comme vous l\’avez vu, Baraat et Y\’mera ont rallié nos forces.\n\nEnaara leur a donné l\’autorisation de venir après bien des contestations, mais elle restera également en retrait avec Sorvos et la capitaine.', '', 68974),
(317797, 'frFR', '<L\’expression de Tala\’saan se durcit.>\n\nNombreux sont mes frères et sœurs qui ont été… emportés par le vortex hurlant de la flèche du Vide.\n\nBeaucoup ont subi des blessures qui vont bien au-delà des blessures physiques.\n\nJe sais ce qu\’ont enduré les braves qui étaient dans la flèche, $n. Vous aussi, vous l\’avez constaté ? La fureur… la confusion… le désespoir.\n\nNous avons perdu tant d\’âmes dans cette guerre. Je ne pouvais exiger de Fareeya l\’impossible.', '', 68974),
(317795, 'frFR', 'Je m\’appelle Tala\’saan, et je suis le commandant voilumière de l\’armée de la Lumière.\n\nÀ la demande de la faillelame Maella, j\’ai accepté de participer à sa mission et de traquer les forces du Vide ainsi que les Hal\’hadar.\n\nNotre histoire avec ces adversaires est complexe, mais nous disposons de tout le nécessaire pour voyager vers des royaumes inconnus.\n\nLes troupes que vous voyez réunies ici figurent parmi l\’élite de l\’unité voilumière.', '', 68974),
(317656, 'frFR', '', 'Tul\’amar serre les dents et reste silencieuse un court instant. Son œil encore fonctionnel se tourne vers vous, puis revient se poser sur Tala\’aasan.', 68974),
(317572, 'frFR', 'Je suivrai de près mon… ou plutôt… notre nouveau pion.', '', 68974),
(317571, 'frFR', 'Il reste encore à faire, mais pas d\’inquiétude : Impotus ne se mettra pas en travers de notre chemin. Il s\’enfermera dans l\’acropole pour savourer sa victoire.', '', 68974),
(317109, 'frFR', 'Ce taudis glacial est faible. Il existe d\’autres mondes qui seraient bien plus propices, bien plus parfaits.', '', 68974),
(316762, 'frFR', 'La faillelame Maella nous a demandé d\’accompagner ses troupes lors de cette expédition.\n\nGrâce à sa connaissance du Vide et des opérations des Hal\’hadar, Veraan s\’est avérée être un atout précieux pour cette mission.\n\nEt moi ? Eh bien, on ne sait jamais quand on peut avoir besoin d\’un technomancien pour démonter quelque chose !', '', 68974),
(316750, 'frFR', '', 'Les archives d\’Antorus ont dévoilé que la présence de la Légion ici, sur Val, était maigre. Quelle surprise.\n\nUne grande partie de ce monde est protégée par d\’énormes tempêtes de grêle, suffisamment puissantes pour transpercer la coque des vaisseaux de la Légion.\n\nAu moins deux vaisseaux d\’invasion ont été détruits lors de leurs tentatives de conquête de ce monde.\n\nQuelques bastions ont finalement été établis, bien qu\’il ne s\’agisse que d\’avant-postes isolés.\n\nIl semblerait que les personnes affectées aux avant-postes sur Val aient généralement été envoyées ici à titre de punition pour leurs échecs répétés.', 68974),
(316562, 'frFR', '', '<L\’archimage Y\’mera apparaît concentrée sur sa tâche, ses mains virevoltant à toute vitesse tandis qu\’elle saisit des symboles runiques sur la console.>\n\nL\’énergie du Vide située au sud provient de l\’acropole.\n\nD\’après ces relevés, la forteresse s\’enfonce très profondément sous la glace.', 68974),
(316520, 'frFR', '', 'Les Illidari connaissent mieux que quiconque cet enfer glacé. La Légion l\’appelait « Val » et utilisait ses températures extrêmes pour interroger les personnes qu\’elle capturait.\n\nUn désert froid et désolé semble être le refuge idéal pour un Domanaar.\n\n<Maella jette un regard peu discret en direction de Décimus.>', 68974),
(316419, 'frFR', '<La balise est équipée de deux boutons permettant de sélectionner une destination de téléportation : Lune-d\’Argent ou la tempête du Vide. Vous devez résister à la tentation d\’appuyer sur les deux boutons en même temps.>', '<La balise est équipée de deux boutons permettant de sélectionner une destination de téléportation : Lune-d\’Argent ou la tempête du Vide. Vous devez résister à la tentation d\’appuyer sur les deux boutons en même temps.>', 68974),
(316274, 'frFR', '', 'Grâce aux impressions holographiques que vous avez récupérées, nous savons où le groupe éthérien se procure les artéfacts draeneï.\n\nIl existe une crypte construite par mon peuple, sous l\’île.\n\nLes Hal\’hadar récupèrent à la fois les gardiens qui s\’y trouvent et les esprits troublés des morts.\n\nLeurs archives indiquent que plusieurs vigilants se trouvent dans la tombe, mais jusqu\’à présent, leurs efforts ont échoué.\n\nAvec un peu de chance, nous pourrons contrecarrer leurs opérations.\n\nTala\’saan dirigera notre expédition dans la crypte.', 68974),
(316214, 'frFR', '', '<Les yeux de l\’archimage Y\’mera s\’écarquillent alors qu\’elle vous prend l\’un des cristaux.>\n\nLes runes inscrites dessus sont draeniques, $n. Cela ne devrait pas me surprendre plus que ça.\n\nLes Hal\’hadar sont des pillards en matière de technologie. Ils picorent les ruines de tous les mondes sur lesquels ils s\’abattent.\n\nIls ont dû découvrir la technologie cristalline de notre peuple ailleurs, tout comme ils ont découvert nos exossatures.\n\nJe vais examiner cela. Apportez le reste à Kifaan, là-bas. Il s\’occupe de répertorier la technologie des Hal\’hadar. \n\nIl serait bon d\’avoir l\’avis d\’un technomancien du Consortium au sujet de cette découverte.', 68974),
(316212, 'frFR', '', '<L\’archimage Y\’mera apparaît concentrée sur sa tâche, ses mains virevoltant à toute vitesse tandis qu\’elle saisit des symboles runiques sur la console.>\n\nAvec un peu de chance et pas mal de déchiffrage, nous pourrons, je l\’espère, comprendre ce que nos adversaires cherchent à accomplir sur Naigtal.\n\nIl y a beaucoup à apprendre sur les Hal\’hadar.\n\nNous ne devons pas gâcher cette opportunité.', 68974),
(314754, 'frFR', 'Vos adversaires sont dans votre dos. Retournez-vous !', 'Vos adversaires sont dans votre dos. Retournez-vous !', 68974),
(313932, 'frFR', '', 'La faillelame Maella observe la projection de Décimus.', 68974),
(313749, 'frFR', '', 'Ah, le moment est venu ? C\’est la faillelame Maella qui vous envoie ? J\’aurais bien besoin de votre aide avant notre départ !\n\nJ\’ai apporté quelques modifications à notre technologie de voilumière, en y ajoutant un simple sort de dissimulation et cette amarre.\n\nJe pense qu\’en combinant tous ces éléments, je pourrai camoufler l\’intégralité de notre camp quand nous atterrirons.\n\nMais avant toute chose, j\’ai besoin de cobayes invisibles pour tester la distance à laquelle nous pouvons positionner l\’amarre.\n\nPourriez-vous m\’aider ?', 68974),
(310380, 'frFR', 'L\’élimination d\’un imperator domanaar n\’a pas la même saveur que le meurtre d\’un chef mortel.', '', 68974),
(310377, 'frFR', '', 'Pertinax ne sera plus un problème pour nous, grâce à notre $uami:amie;.', 68974),
(310376, 'frFR', 'Et si leur « imperator » daigne vous honorer de sa présence, j\’apprécierais que vous débarrassiez ce désert de sa personne.', '', 68974),
(310375, 'frFR', '', 'En neutralisant ici la présence du Vide, nous offrons un repos bien mérité à Azeroth. Semez le chaos.', 68974),
(310366, 'frFR', 'Lumière… gangrène… Vide. Le mélange parfait pour une tension affligeante. Délicieux.', '', 68974),
(309048, 'frFR', 'Les Hal\’hadar ont armé leurs esquifs volants de tourelles à énergie, pour « se protéger ». Cela vous dit de tester leurs protections ?', '', 68974),
(309047, 'frFR', 'Je connais très peu ces « Hal\’hadar », mais je les trouve bien plus formidables que l\’Ombre-Garde. Je vous suggère de réduire leur nombre, histoire de ne pas vous faire submerger.', '', 68974),
(309020, 'frFR', '', 'Notre équipe de reconnaissance sancteforge a des preuves qu\’une ancienne créature du Vide vivait ici. Récupérez des échantillons pour notre recherche.', 68974),
(309018, 'frFR', 'Votre « audacieuse » équipe de reconnaissance a tenté d\’utiliser les ressources volatiles de ce monde. Évitez les incidents malencontreux en les collectant.', '', 68974),
(309015, 'frFR', '', 'Le sabotage du réseau de portails domanaar enrayerait leur invasion d\’Azeroth. Faites de votre mieux et ralentissez leurs efforts.', 68974),
(309014, 'frFR', 'Sans surprise, une autre « menace » compromet votre mission. Détruisez, éliminez, réussissez.', '', 68974),
(318546, 'frFR', 'La terrasse des Magistères a toujours été un lieu d\’apprentissage.\n\nUn bastion de connaissances où les idées peuvent être partagées sans distinction ni ego.\n\nEt pourtant, malgré tous mes efforts, j\’ai du mal à regarder les personnes qui sont revenues sans me sentir…\n\n<Le magistère serre les dents et se tait.>', 'La terrasse des Magistères a toujours été un lieu d\’apprentissage.\n\nUn bastion de connaissances où les idées peuvent être partagées sans distinction ni ego.\n\nEt pourtant, malgré tous mes efforts, j\’ai du mal à regarder les personnes qui sont revenues sans me sentir…\n\n<La magistrice serre les dents et se tait.>', 68974),
(318542, 'frFR', '<Le magistère haut-elfe soupire à votre approche.>\n\nJe vous en prie, ne me criez pas dessus simplement parce que je suis là. Je ne pourrais supporter un énième regard noir ou commentaire acerbe.\n\nJe souhaite juste apprendre la magie et m\’entraîner à lancer de nouveaux sorts, c\’est trop demander ?\n\nCes querelles me rendent fou !', '<La magistrice haute-elfe soupire à votre approche.>\n\nJe vous en prie, ne me criez pas dessus simplement parce que je suis là. Je ne pourrais supporter un énième regard noir ou commentaire acerbe.\n\nJe souhaite juste apprendre la magie et m\’entraîner à lancer de nouveaux sorts, c\’est trop demander ? \n\nCes querelles me rendent folle !', 68974),
(317974, 'frFR', 'La maîtrise et la compréhension de la magie ont toujours été notre voie. La voie des Magistères.\n\nJ\’espère cependant que quelques-uns de mes semblables à l\’esprit un peu plus ouvert pourront en aider d\’autres à comprendre pourquoi nous souhaitons étudier le Vide.\n\nEt nous n\’avons nullement l\’intention de menacer d\’exil quiconque ne souhaite pas participer à cette étude.', 'La maîtrise et la compréhension de la magie ont toujours été notre voie. La voie des Magistères.\n\nJ\’espère cependant que quelques-uns de mes semblables à l\’esprit un peu plus ouvert pourront en aider d\’autres à comprendre pourquoi nous souhaitons étudier le Vide.\n\nEt nous n\’avons nullement l\’intention de menacer d\’exil quiconque ne souhaite pas participer à cette étude.', 68974),
(317973, 'frFR', 'D\’après Veldharin, les tout premiers chercheurs et chercheuses de connaissance ont enquêté sur une présence maléfique que nos ancêtres ont ressentie lors de leur arrivée en Tirisfal.\n\nPersonne ne sait exactement quelle a été leur découverte. Apparemment, très peu n\’ont pas sombré dans la démence.\n\nEn tout cas, leurs mésaventures ont poussé Dath\’Remar à bannir la magie du Vide.\n\nVous pensez qu\’Umbric a pu la contempler ? Et que nous aussi, nous le pourrons ?', 'D\’après Veldharin, les tout premiers chercheurs et chercheuses de connaissance ont enquêté sur une présence maléfique que nos ancêtres ont ressentie lors de leur arrivée en Tirisfal.\n\nPersonne ne sait exactement quelle a été leur découverte. Apparemment, très peu n\’ont pas sombré dans la démence.\n\nEn tout cas, leurs mésaventures ont poussé Dath\’Remar à bannir la magie du Vide.\n\nVous pensez qu\’Umbric a pu la contempler ? Et que nous aussi, nous le pourrons ?', 68974),
(317972, 'frFR', '<Le magistère soupire à votre approche.>\n\nJe vous en prie, ne me criez pas dessus simplement parce que je suis là. Je ne pourrais supporter un énième regard noir ou commentaire acerbe.\n\nJe souhaite juste apprendre la magie et m\’entraîner à lancer de nouveaux sorts, c\’est trop demander ?\n\nCes querelles me rendent fou, et c\’est peu dire quand on sait que j\’ai déjà contemplé un trou noir !', '<La magistrice soupire à votre approche.>\n\nJe vous en prie, ne me criez pas dessus simplement parce que je suis là. Je ne pourrais supporter un énième regard noir ou commentaire acerbe.\n\nJe souhaite juste apprendre la magie et m\’entraîner à lancer de nouveaux sorts, c\’est trop demander ? \n\nCes querelles me rendent folle, et c\’est peu dire quand on sait que j\’ai déjà contemplé un trou noir !', 68974),
(317917, 'frFR', 'En toute honnêteté, j\’ignore si c\’était vraiment là son intention.\n\nLa façon dont il a trahi la Convocation et notre peuple était absolument ignoble, mais malgré tout, je ne l\’imagine pas endommager l\’Omnium.\n\nJamais il n\’aurait tenté de détruire toutes ces données contenant des connaissances interdites, alors qu\’on lui en avait refusé l\’accès pendant si longtemps.\n\nJe m\’attendais plutôt à ce qu\’il tente de voler l\’Omnium dans son intégralité.\n\nC\’est sans doute pour cette raison qu\’il a décidé de n\’en dérober qu\’une partie.', '', 68974),
(317753, 'frFR', '<Il plisse ses yeux vitreux.>\n\nVoilà une question… pertinente.\n\nC\’était un réservoir de connaissances prohibées, comme l\’avait décrété Dath\’Remar.\n\nLorsque nous avons mis pied pour la première fois sur les rivages de Tirisfal, nos ancêtres ont dû affronter une obscurité qui imprégnait cette terre.\n\nLes murmures ont réduit beaucoup de membres de mon peuple à la folie. Ils se nourrissaient de notre paranoïa, attisant la peur et la jalousie parmi nos sœurs et nos frères épuisés.\n\nDath\’Remar cherchait à comprendre d\’où venait cette magie et il a donc envoyé les premiers chercheurs et chercheuses.\n\nNul ne sait ce qu\’ils ont trouvé ou affronté, mais c\’était assez pour pousser Dath\’Remar à abandonner l\’étude.\n\nLes magistères les plus fiables et exemplaires uniquement pouvaient sonder les connaissances contenues dans la magicule de Vide.', '', 68974),
(317750, 'frFR', 'Une excellente question ! Voyons voir…\n\nNous avons la magicule des arcanes, bien sûr. Des milliers d\’années de savoir bien-né ont fourni à notre peuple naissant les ressources pour lui permettre de prospérer sur cette nouvelle terre.\n\nNous avons la magicule de feu et les autres magicules élémentaires. Les fondements naturels de notre monde même.\n\nNous avons une intrigante collection de connaissances sacrées à l\’intérieur de la magicule de Lumière. Les grands prêtres de Lune-d\’Argent ont beaucoup contribué à ses connaissances.\n\nEt, puisque tout le monde pose la question, il y a les magicules interdites…\n\nCelle de Vide. De gangrène. De nécromancie… Bien que j\’imagine que certaines restrictions à leur égard pourraient être… assouplies.\n\n<Veldharin fronce les sourcils d\’un air songeur.>', '', 68974),
(317749, 'frFR', 'Je vous invite à consulter la plaque de l\’Omnium. Elle synthétise admirablement bien les desseins de Dath\’Remar.\n\nPour faire court, ses motivations étaient multiples, ses aspirations hardies et sa mission aussi limpide que les cieux des Chants éternels.\n\nDath\’Remar a été témoin de beaucoup en sa jeunesse et il n\’a jamais craint d\’affronter les puissances magiques de notre univers.', '', 68974),
(317748, 'frFR', 'Bien sûr que oui, et pas seulement pour l\’Omnium !\n\nJ\’ai perdu deux frères et ma chère sœur quand la cité est tombée. Tous les trois étaient magistères…\n\nJ\’ai tenté d\’aider le jeune prince à le ranimer… l\’éveiller ? Il était si… froid.\n\nMais nous avions beau essayer, il… demeurait inerte. Même son code-clé est resté sans effet.\n\nQuand il a été scellé, j\’ai essayé d\’aider les magistères qui avaient survécu à restaurer la terrasse… mais ils ont insisté pour que je me repose.\n\nEt c\’est ce que j\’ai fait, pendant de nombreuses années. Certaines étaient… moins bonnes que d\’autres. Mais me voilà de retour et le jeune Rommath n\’était pas d\’humeur à tenter de m\’arrêter.\n\nAprès toutes ces années, cette fin de retraite est précisément ce dont j\’avais besoin !', '', 68974),
(317746, 'frFR', 'Bon, si j\’insistais pour que vous posiez une question, je pensais que vous vous intéresseriez à l\’Omnium et pas à moi. Mais puisque ma vie vous passionne…\n\nJe suis le gardien Veldharin, nommé protecteur du savoir par la grande magistrice… euh… comment c\’était son nom, déjà ?\n\nLa grande magistrice Mo… non, ce n\’était pas elle. Bref, peu importe. Il y a plusieurs grands magistères de cela.\n\nAprès la Deuxième guerre, l\’on m\’a incité à prendre ma retraite. Apparemment, Anasterian voulait que je profite des nombreux jours qu\’il me restait à vivre.\n\nC\’était sa façon de dire que j\’étais bien trop vieux pour occuper ce poste. Je suis donc allé vivre avec ma fille, Elsharin.\n\nElle travaillait comme chercheuse de la connaissance et ambassadrice des Magistères au sanctuaire du Sorcier, à Hurlevent.', '', 68974),
(317744, 'frFR', 'Bienvenue au Lycaneum !\n\nVous vous tenez en présence d\’un savoir illimité et d\’un potentiel magique infini !\n\nJe parle bien sûr de l\’Omnium de Haut-Soleil. Je n\’en suis que l\’humble gardien.\n\nJe suis ici pour guider les jeunes magistères dans leur parcours académique et magique.\n\nSi vous avez la moindre question, n\’hésitez pas.', '', 68974),
(317738, 'frFR', 'À votre avis, pourquoi les appelle-t-on des magicules ? Pourquoi pas manacules ? Attendez, ça ressemble à manucure.\n\nOmnicules, alors ? Ou est-ce… Omni-coule ?\n\nPar Dath\’Remar, est-ce que je les prononce mal depuis tout ce temps ?', 'À votre avis, pourquoi les appelle-t-on des magicules ? Pourquoi pas manacules ? Attendez, ça ressemble à manucure.\n\nOmnicules, alors ? Ou est-ce… Omni-coule ?\n\nPar Dath\’Remar, est-ce que je les prononce mal depuis tout ce temps ?', 68974),
(317730, 'frFR', 'La terrasse n\’avait pas connu un tel chaos magique depuis… eh bien… votre méfait avec le magistère Umbric.\n\n<Le brise-sort vous détaille du regard.>\n\nTâchez de bien vous tenir, cette fois.', 'La terrasse n\’avait pas connu un tel chaos magique depuis… eh bien… votre méfait avec le magistère Umbric.\n\n<La brise-sort vous détaille du regard.>\n\nTâchez de bien vous tenir, cette fois.', 68974),
(317724, 'frFR', 'Surveillez votre conduite dans ces couloirs, $c.\n\nCeci est peut-être la terrasse des Magistères, mais nous y appliquons les règles de la magie au pied de la lettre.', 'Surveillez votre conduite dans ces couloirs, $c.\n\nCeci est peut-être la terrasse des Magistères, mais nous y appliquons les règles de la magie au pied de la lettre.', 68974),
(317723, 'frFR', '<Le brise-sort plisse les yeux en vous observant et esquisse un léger sourire narquois.>\n\nNe vous inquiétez pas, $n. Je ne brandirai pas mon glaive contre vous.\n\nOn m\’a dit que vous agissiez sous l\’autorité du seigneur régent, lors de votre dernière visite. Sachez bien que ma réaction n\’était nullement personnelle.\n\nJe respecte le serment sacré des brise-sorts et… cette malheureuse série d\’évènements sur la terrasse aurait dû se régler entre les cours et les Magistères, pas entre vous et moi.\n\nCela dit, je vous suis reconnaissant de ne pas m\’avoir tué.', '', 68974),
(317722, 'frFR', '<Rommath plisse les yeux un instant.>\n\nUmbric et ses… adeptes devront se conformer aux règlements concernant l\’Omnium.\n\nJe ne tolérerai pas une démonstration magique des horreurs du Vide simplement parce que les Ren\’dorei sont incapables de suivre des règles.\n\nNéanmoins, bien que j\’aie toujours peu foi dans la voie qu\’Umbric a suivie, je pourrais être enclin à lui faire confiance… pour l\’instant.\n\nLa maîtrise du Vide que son peuple revendique pourrait mener à des échanges plus… éclairés concernant la magicule de Vide.\n\nToutefois, je ne permettrai pas que la magie du Vide devienne un nouveau programme d\’études pour les Magistères de cette terrasse !', '', 68974),
(317721, 'frFR', 'L\’étude de la connaissance contenue à l\’intérieur est réservée aux Magistères, et il existe même des restrictions à cet égard.\n\nDath\’Remar en personne a mis en place des règles et des règlements il y a de ça des générations.\n\nCela nous permet de découvrir et de cataloguer les nouvelles magies dangereuses tout en nous prévenant de la nature imprévisible de ces forces.\n\nCela dit, il fut un temps où l\’accès à la magicule de gangrène était strictement interdit.\n\nQuand je pense à la rapidité avec laquelle les choses évoluent…', '', 68974),
(317719, 'frFR', '<Umbric affiche un sourire et jette un œil à Rommath.>\n\nRommath tolère… à peine mes recherches, mais l\’Omnium a toujours été soumis à de strictes mesures de protection et de régulation.\n\nFort heureusement, il ne s\’agit pas d\’un recueil de toutes les magies disponible à quiconque serait intéressé.\n\nJe frissonne à l\’idée de ce qu\’aurait pu accomplir Dar\’Khan si on lui en avait accordé l\’accès.\n\nLes règlements mis en place existent depuis l\’époque de Dath\’Remar.\n\nSes premières confrontations avec le Vide ou la dévastation dont il a été témoin, causée par la gangrène durant la guerre des Anciens, sont précisément les raisons pour lesquelles ces magies ont été interdites.\n\nNéanmoins, peut-être y a-t-il matière à discussion.', '', 68974),
(317717, 'frFR', 'Une question que tout le monde se pose depuis qu\’il est devenu silencieux.\n\nNul ne sait précisément ce qui s\’est passé. Nous connaissons seulement l\’état dans lequel il a été découvert.\n\nJe n\’étais pas présent quand la terrasse est tombée… quand Dar\’Khan est arrivé… mais j\’en ai vu les conséquences.\n\nJe n\’avais jamais vu l\’Omnium aussi vide. Il n\’en émanait pas la moindre lueur de pouvoir. Aucune magicule dans les parages.\n\nCe n\’était qu\’une structure vide et silencieuse. C\’était pour le moins… troublant.', '', 68974),
(317715, 'frFR', 'Lorsque nous l\’avons trouvé, nous n\’avons découvert qu\’une structure vide dans les décombres. Il n\’y avait aucune magicule et aucune lueur runique n\’en émanait.\n\nHormis les restes du carnage perpétré par Dar\’Khan, il paraissait inerte.\n\nLes magicules ont été créées comme des extensions de l\’Omnium. Nous n\’avons pas pensé qu\’il pouvait s\’agir de composants manquants.\n\nQuand la relique s\’est éveillée et que les magicules sont réapparues, nous avons remarqué que la matrice centrale était vide.\n\nJamais nous n\’avions constaté cette anomalie.\n\nCependant, une chose était sûre : la magicule qui avait été consultée en dernier avait disparu ou avait été détruite. Ou, dans ce cas bien précis, volée.', '', 68974),
(317714, 'frFR', 'Au début, oui.\n\nNous savions qu\’il s\’était rendu sur la terrasse pour massacrer la Convocation. Les éclaboussures de sang sur les murs et l\’Omnium en étaient la preuve.\n\nCependant, lorsque nous avons perquisitionné ses recherches et sa demeure, nous n\’avons découvert que son obsession pour les magies noires.\n\nUmbric a ensuite souligné que Dar\’Khan était motivé par le pouvoir et la connaissance, et qu\’endommager l\’Omnium allait à l\’encontre de ses… aspirations.', '', 68974),
(317713, 'frFR', 'Je… ne peux pas répondre à cette question.\n\nSachez seulement que nous avons tout essayé pour éveiller l\’Omnium. Même le code-clé des Haut-Soleil n\’a eu aucun effet sur lui.\n\nKael\’thas était… en deuil.\n\nComme nous, il avait perdu tant de choses en si peu de temps.\n\nIl cherchait désespérément des réponses à notre détresse. Pour notre peuple.\n\nLe savoir contenu dans l\’Omnium aurait peut-être pu nous aider… ou guider le prince.\n\nMais face à son silence, nous étions dans une impasse.', '', 68974),
(316792, 'frFR', 'Code-clé des Haut-soleil non reconnu. Empreinte d\’écho miroir initialisée.', 'Code-clé des Haut-soleil non reconnu. Empreinte d\’écho miroir initialisée.', 68974),
(315312, 'frFR', 'Voici la flèche d\’Aubétoile. C\’est en ce lieu agréable et paisible que Dar\’Khan Drathir a grandi.\n\nSuite à mon exil de Lune-d\’Argent, j\’ai cherché à récupérer plusieurs éléments de ses recherches sur le Vide, ce qui m\’a mené ici.\n\nApparemment, une bonne partie de ses découvertes est restée cachée. C\’est au sommet de cette tour que j\’ai ouvert pour la première fois la faille vers Telogrus.\n\nJ\’ignorais qu\’il restait d\’autres secrets ici…', '', 68974),
(314998, 'frFR', 'Nous n\’avons jamais nommé de $uchercheur:chercheuse; qui n\’appartenait pas à l\’ordre des Magistères, mais vous êtes $uun candidat:une candidate;… absolument unique.\n\nUmbric ou moi vous confierons les tâches de recherche que vous devrez accomplir.\n\nEn échange, nous vous fournirons une série de puissants enchantements runiques qui renforceront vos pouvoirs.\n\nVous retrouverez ces runes dans votre feuillet de l\’Omnium. Libre à vous de choisir lesquelles renforcer.\n\nDes questions ?', '', 68974),
(314900, 'frFR', '<Rommath fixe l\’Omnium inactif.>\n\nNous y sommes presque. Maintenant que nous avons récupéré le code-clé de Belo\’vir et que vous avez retrouvé la magicule de Vide avec Umbric, il ne nous reste qu\’une chose à faire.\n\nC\’est maintenant ou jamais, $n. Êtes-vous $uprêt:prête; ?', '', 68974),
(314899, 'frFR', 'J\’ai étudié l\’Omnium pendant des années. Comme chaque magistère avant moi, j\’ai appris tout ce qu\’il avait à offrir : runes, sorts, incantations, tout.\n\nLe jour où il est devenu inactif fut un jour sombre, pour de nombreuses raisons. Je n\’aurais jamais imaginé l\’entendre bourdonner à nouveau. Tout ce chemin parcouru… c\’est incroyable.', '', 68974),
(314791, 'frFR', 'Belo\’vir semble avoir laissé des instructions pour accéder à la chambre forte… Ces dernières m\’attendent depuis très longtemps.\n\nConnaissant mon prédécesseur, il a sans doute compliqué les choses d\’une manière digne de sa maîtrise des images miroirs.\n\nNous allons devoir nous diviser pour mieux régner. Je vais aller dans mon bureau à l\’étage et m\’occuper des protections les plus ardues.\n\nPouvez-vous aider mes images miroirs à démêler les trois qui se trouvent aux niveaux extérieurs ?', '', 68974),
(314746, 'frFR', 'Je ne peux m\’empêcher de me demander depuis combien de temps Dar\’Khan convoitait les secrets interdits que renferme la magicule de Vide.\n\nLorsque nous avons rejoint les Magistères, on nous a dispensé des cours sur les écoles de magie et leurs magicules qui étaient proscrites pour l\’assemblée générale.\n\nDar\’Khan manifestait déjà un certain penchant pour le Vide pendant nos premières années à Dalaran, je savais donc qu\’il nourrissait une sorte de fascination.\n\nLa convoitait-il depuis le jour où nous avons mis les pieds au Lycaneum ?\n\nOu s\’agissait-il d\’une décision impulsive, prise dans un élan d\’audace alors qu\’il massacrait ses semblables sur la terrasse ?', '', 68974),
(314744, 'frFR', 'Il fut un temps où je pensais avoir découvert tous les secrets de Dar\’Khan enfouis en ce lieu. Les évènements d\’aujourd\’hui étaient… inattendus.\n\nPar précaution, et parce que je sais que Rommath me le demandera, je vais m\’assurer que plus rien ne puisse nous surprendre ici.\n\nJe vais nettoyer le lieu de notre rituel et je vous rejoindrai sur la terrasse des Magistères après que vous aurez aidé Rommath à récupérer le code-clé de Belo\’vir.', '', 68974),
(314678, 'frFR', 'Mes soupçons étaient fondés… La sentez-vous dans l\’air, $n ? Cette pulsation froide et distante… comme un battement de cœur.\n\nJe pense qu\’il s\’agit du composant que nous cherchons, mais il est invisible.\n\nAvec le bon sort et de la concentration, le Vide peut révéler les secrets enfouis ici par Dar\’Khan.\n\nPendant que vous connectez les ancres, je m\’occupe de finaliser ce sort.\n\nPrenez garde : le Vide nous happe déjà, nous appelant vers notre destin.', '', 68974),
(310354, 'frFR', 'Il faudra désactiver ses protections. Je retrouverai notre brave $uami:amie; là-bas.', '', 68974),
(310059, 'frFR', 'Les arcanes, la gangrène ou même la Lumière et… le Vide, Dath\’Remar a créé l\’Omnium pour y préserver le savoir.', '', 68974),
(317919, 'frFR', 'J\’imagine que c\’est le cas pour beaucoup.\n\nD\’ordinaire, je renvoie toutes les questions à notre gardien de la connaissance qui a récemment repris du service, Veldharin.\n\nMais, compte tenu de votre implication dans la restauration de l\’Omnium, je vais satisfaire votre curiosité.', '', 68974),
(317754, 'frFR', 'Ah, oui. La magicule de gangrène. Un réservoir de connaissances prohibé, ou du moins il l\’a été.\n\nSelon Dath\’Remar, la gangrène était l\’une des premières magies à avoir servi de catalyseur pour la création de l\’Omnium.\n\nIl a perçu son potentiel… et l\’horreur qu\’elle pouvait provoquer durant les jours des Bien-nés. Il a vu les créatures d\’outremonde qui maniaient la magie gangrenée.\n\nLe moment venu, il a constaté la vérité destructrice, tant de la magie gangrenée que celle des arcanes, pendant les derniers jours de la guerre des Anciens.\n\nJamais plus il ne permettrait que son peuple soit pris au dépourvu par une force destructrice et inconnue.\n\nAvec le temps, la connaissance de la magie gangrenée et de la Légion ardente a été partagée entre les Magistères et le Conseil de Tirisfal.\n\nMais hormis pour quelques magistères bénéficiant de certains privilèges, l\’étude de la magicule de gangrène était interdite.\n\nAh, comme les temps allaient changer…', '', 68974),
(317573, 'frFR', 'Ce monde… tout son potentiel… est désormais à moi.', '', 68974),
(309931, 'frFR', 'Forestiers, forestières, préparez-vous ! Montrez à ces monstres pourquoi c\’est nous qui défendons l\’enclave !', 'Forestiers, forestières, préparez-vous ! Montrez à ces monstres pourquoi c\’est nous qui défendons l\’enclave !', 68974),
(307084, 'frFR', 'Ah, $n.\n\nQuel plaisir de voir une tête moins maussade à cette table. On commence à nouveau à me tolérer dans cette ville, mais entendez-moi bien, Rommath ne va pas tarder à réutiliser sa spécialité, le projectile transféré.\n\nVoyez-vous, il a combiné les projectiles des arcanes avec un sort de transfert, en guise de leçon pour tout être assez stupide pour le défier, à l\’époque.\n\nIl n\’aime pas l\’admettre, mais c\’est moi qui lui ai donné l\’idée d\’ajouter un sort d\’invisibilité aux projectiles afin que les adversaires ne puissent pas les voir arriver.\n\nEnfin, Lor\’themar m\’a autorisé à rester, et je ne peux que me réjouir de l\’inconfort que ma présence inspire.', '', 68974),
(306595, 'frFR', 'Nous… Nous devons prévenir Lor\’themar. Nous vous retrouverons plus tard, $p.', '', 68974),
(304405, 'frFR', 'En temps de guerre et de conflits, nos anciens protecteurs ont toujours été une force inflexible sur le champ de bataille.\n\nMais cela demande un effort considérable pour les réveiller.\n\nJe vais demander à l\’équipe de soins de combat de l\’ancien Vertécorce de vous suivre. Cherchez des pierres et des rochers suffisamment gros pour que l\’ancien puisse les lancer sur nos adversaires.\n\nIl refuse de se réveiller tant qu\’il n\’a rien à lancer.', 'En temps de guerre et de conflits, nos anciens protecteurs ont toujours été une force inflexible sur le champ de bataille.\n\nMais cela demande un effort considérable pour les réveiller.\n\nJe vais demander à l\’équipe de soins de combat de l\’ancien Vertécorce de vous suivre. Cherchez des pierres et des rochers suffisamment gros pour que l\’ancien puisse les lancer sur nos adversaires.\n\nIl refuse de se réveiller tant qu\’il n\’a rien à lancer.', 68974),
(303273, 'frFR', '', 'Les anciens protecteurs sont de puissantes armes de siège qui ravagent les lignes arrière ennemies lors des batailles.\n\nLa Horde ne connaît que trop bien leur puissance destructrice.', 68974),
(300503, 'frFR', '', 'C\’est impossible. Je l\’ai envoyé magiquement à Ulen, mon sénéchal en charge pendant mon absence. Quelque chose se trame à Suramar.', 68974),
(292933, 'frFR', 'Eh bien… Elle a demandé beaucoup de travail, et vous la méritez.', '', 68974),
(289958, 'frFR', '', 'Le Concordat argenté revient à Lune-d\’Argent, une dernière fois.', 68974);
